/* Post-seminar reference pages. Existing learning/project stores remain authoritative. */
(()=>{
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const sections=[['home/journey','The journey'],['workbook','My work']];
 const nav=()=>`<nav class="seminar-nav" aria-label="REI sections">${sections.map(([id,label])=>`<a href="#${id}">${label}</a>`).join('')}</nav>`;
 const shell=(title,intro,body)=>`<div class="seminar-page">${nav()}<header><h1>${title}</h1><p class="seminar-intro">${intro}</p></header>${body}</div>`;
 const row=(href,title,description)=>`<a class="seminar-row" href="${href}"><strong>${title}</strong><span>${description}</span><b aria-hidden="true">↗</b></a>`;
 const sessions=[
 ['Research mindset','An observation is a starting point, not an explanation.','An Isabel campus queue may reflect arrival patterns, service time or staffing. Do not assume students are the cause.','Write one observation and two possible explanations.','#learn/0'],
 ['A meaningful problem','Narrow the people, place, measure and purpose.','IE: What are the observed waiting times at one Isabel campus service desk during selected enrollment hours?','State your question and what evidence you can access.','#library/question'],
 ['Search and evaluate','Search concept groups; check what each source can support.','IT: Try ("offline learning" OR "offline access") AND (student OR undergraduate), then assess relevance to a Leyte campus. A Leyte-only search may miss useful methods.','Record a database, query, date and reason for keeping one source.','#create/search'],
 ['Literature and synthesis','Compare studies around a theme, including their differences.','Education: Compare how studies define reading comprehension before adapting a reading-support question for one Isabel school.','Compare two sources by method, finding and limitation.','#library/synthesis'],
 ['Objectives and methods','Each objective needs evidence and a matching analysis.','Science: Describe pH variation in selected Leyte stream samples using defined locations, calibrated equipment and a sampling schedule. pH alone cannot establish drinking-water safety.','Map one question → objective → data → analysis.','#library/method'],
 ['Writing and review','Link each claim to evidence and keep the study boundary visible.','A volunteer survey from one Leyte campus cannot establish what all Leyte students experience.','Revise one overbroad claim; ask a peer what evidence is missing.','#library/claim']
 ];
 function recap(){return shell('Your seminar, within reach.','A short refresher for independent work after the seminar. These summaries follow REI’s existing workshop sequence; examples are fictional, not local findings.',`<a class="button primary" href="${resume()}">${resume()==='#learn'?'Start here':'Continue where you left off'}</a><div class="recap-sessions">${sessions.map(([title,idea,example,action,href])=>`<section><h2>${title}</h2><p><strong>Keep:</strong> ${idea}</p><p><strong>Example:</strong> ${example}</p><p><strong>Now do this:</strong> ${action}</p><a href="${href}">Open the matching lesson or tool ↗</a></section>`).join('')}</div><section><h2>Keep these beside your draft</h2>${row('#chapters','Chapters 1–4 map','Follow the thread from problem to results.')}${row('#library/ethics','Ethics, citation and honest AI use','A five-minute check before writing or recruiting.')}${row('#tools/checklists','Quick self-checks and FAQs','Gap, source coverage and title scope.')}</section>`)}
 function ethics(){return shell('Use ideas honestly. Treat people fairly.','Lesson 7 of 7 · Read, practise, apply. You will practise crediting a source, recognizing plagiarism and planning responsible consent and AI use.',`<article class="seminar-reading"><section><h2>Cite the idea; mark the exact words</h2><p>APA 7 uses author and year in the text, linked to a full reference. A paraphrase still needs a citation. For exact words, use quotation marks (or block format for 40 or more words) and a page number; use an appropriate paragraph or section locator when pages are absent.</p><p><strong>Fictional format example:</strong> A paraphrase ends with (Dela Cruz, 2024). A short quotation ends with (Dela Cruz, 2024, p. 12). This author and publication are illustrative, not a source to cite.</p><p><strong>Journal reference pattern:</strong> Author, A. A. (Year). Article title. <em>Journal Title, volume</em>(issue), pages. DOI URL when available. Check author order, title, year and DOI against the original. A reference list alone does not credit an uncited passage.</p></section><section><h2>Plagiarism is more than copying a paragraph</h2><p>Uncredited ideas, copied images or code, submitting someone else’s work, and patchwriting—changing a few words while retaining a source’s wording or structure—can misrepresent authorship. A citation does not make unmarked copied wording a paraphrase. Follow course rules on reuse of your earlier submissions.</p><p><strong>Try this:</strong> Read the source, close it, explain the idea in your own structure, then reopen it to check accuracy and add the citation. Keep exact quotations separate from your notes.</p></section><section><h2>Consent comes before participation</h2><p>For an Isabel student interview, explain the purpose, activities, time, risks, benefits, privacy, storage, contacts and voluntary choice in language the participant understands. Refusing should not affect grades or services. Explain withdrawal and any practical limit after anonymization. Ask separately before recording. Gatekeeper permission is not the participant’s consent.</p><p>Follow your institution’s ethics review process before recruitment; additional safeguards apply to minors and vulnerable participants. Collect only necessary information, restrict access and agree a retention/deletion plan. Do not promise anonymity if you retain identifying recordings.</p></section><section><h2>Use AI with permission and a record</h2><p>Check your teacher’s and institution’s policy first. If permitted, disclose the tool/version, date, purpose and how you checked or revised its output. Verify every reference and factual claim in the original source. Do not invent sources, interviews or data, or submit generated work as wholly your own. Do not upload identifiable participant information or confidential drafts without appropriate authorization.</p><p><strong>Disclosure pattern:</strong> “I used [tool/version] on [date] for [permitted task]. I checked [sources/calculations] and revised [parts]. I remain responsible for the submitted work.” Adapt this to the required policy; disclosure does not make prohibited use acceptable.</p></section><section><h2>Check your decision</h2><fieldset><legend>You change a few words in a source paragraph, add (Author, year), and keep its sentence structure. What should you do?</legend><label><input type="radio" name="ethics-check" value="copy"> Submit it because a citation is present.</label><label><input type="radio" name="ethics-check" value="revise"> Rewrite the idea in my own structure and cite it, or quote the exact wording with a locator.</label></fieldset><p data-ethics-feedback role="status">Choose an answer. This practice is not graded or saved.</p></section><section><h2>Now do this</h2><p>Audit one paragraph, add missing citations, and write a consent or AI-use question to ask your adviser before proceeding.</p><a href="#workbook">Open My Workbook ↗</a></section><details><summary>Sources and policy checks</summary><ul><li><a href="https://apastyle.apa.org/style-grammar-guidelines/citations">APA Style: in-text citations</a></li><li><a href="https://apastyle.apa.org/style-grammar-guidelines/citations/plagiarism">APA Style: plagiarism</a></li><li><a href="https://privacy.gov.ph/wp-content/uploads/2023/11/NPC-Circular-No.-2023-04_Guidelines-on-Consent_07Nov2023.pdf">National Privacy Commission: consent guidance</a></li><li><a href="https://www.unesco.org/en/articles/guidance-generative-ai-education-and-research">UNESCO: generative AI in education and research</a></li></ul><p>This is a short learning guide. Your institution determines the required ethics review, thesis format and permitted AI use.</p></details></article>`)}
 const chaptersData=[
 ['1','The problem and its purpose','Context and evidence of the problem; bounded gap; research questions and objectives; significance; scope and definitions.','A waiting-time problem at one Isabel campus desk becomes an objective to describe waits during specified hours.','The same population, setting and measures must guide Chapter 2’s review and Chapter 3’s design.','A broad title promises an effect, but the objective only describes opinions.'],
 ['2','What the literature makes possible','Organize relevant studies by themes, compare methods and findings, explain a framework and justify what remains uncertain.','Compare queueing and service-time studies; explain why their settings or measures may differ from your proposed site.','Use the review to refine the Chapter 1 gap and justify Chapter 3’s measures and analysis.','A list of article summaries ends with “no local study” without showing a meaningful uncertainty.'],
 ['3','How the question will be answered','Design; site and selection; participants/materials; instruments; procedures; analysis; consent, privacy and other ethics safeguards.','Specify observation periods, a consistent waiting-time definition, selection and descriptive summaries; obtain the required permissions.','Every objective from Chapter 1 has a data source and analysis that can produce a Chapter 4 answer.','The instrument measures satisfaction while the objective asks about waiting time.'],
 ['4','What the evidence says','Present actual results by research question, with clear tables or qualitative themes, interpretation and limits. Placement of discussion varies by school.','After approved data collection, report observed waits and their variation; explain missing observations. Never invent results in a proposal.','Answer the original objectives and discuss findings against Chapter 2 without exceeding Chapter 3’s design.','Results introduce a new question, imply causation from descriptions, or contain fabricated data.']
 ];
 function chapters(){return shell('One study. Four connected chapters.','A common thesis structure, not a substitute for your department’s manual. Some disciplines place the review in Chapter 1 or use a different Chapter 4. Confirm the required format with your adviser.',`<p class="seminar-thread">Problem → question → objective → evidence → analysis → bounded answer</p><p><strong>Fictional IE example:</strong> waiting times at one campus service desk in Isabel, Leyte. No local measurements have been collected for this example.</p><div class="chapter-map">${chaptersData.map(([n,title,contents,example,link,mistake])=>`<section><h2>Chapter ${n}: ${title}</h2><dl><dt>Include</dt><dd>${contents}</dd><dt>Example</dt><dd>${example}</dd><dt>Carry forward</dt><dd>${link}</dd><dt>Common mistake</dt><dd>${mistake}</dd></dl></section>`).join('')}</div><section><h2>Check your alignment in one row</h2><p>What is the observed waiting-time pattern? → Describe waits → Time-stamped observations → Descriptive summaries → Answer only for the observed periods and site.</p><p>For a proposal, plan how Chapter 4 will answer each objective; leave results empty until you have actual data.</p><a class="button primary" href="#workbook">Apply this to My Workbook</a></section>`)}
 const peer=['Can I identify the problem, population/materials and setting?','Does each objective match a research question?','Does the review compare sources and justify a bounded gap?','Can the planned evidence and analysis answer each objective?','Are claims, quotations, images and code attributed appropriately?','Are consent, permissions, privacy and AI disclosures addressed?','What is one strength, one unanswered question and one specific next revision?'];
 const pitch=[['0:00–0:30','Problem and people','What specific problem matters, to whom, and where? Name evidence you have actually checked.'],['0:30–1:00','Gap and question','What remains uncertain in the sources reviewed? State one bounded question and objective.'],['1:00–2:00','Plan and safeguards','Explain participants/materials, selection, data collection, analysis, feasibility and consent/privacy.'],['2:00–2:40','Contribution and boundary','What could the study contribute? Say what it cannot establish. For proposals, describe expected contribution, not invented findings.'],['2:40–3:00','Ask for feedback','Name the most important unresolved decision and ask one precise question.']];
 const templateText=id=>id==='peer'?'# Peer-review checklist\n\nReviewer: ____  Writer: ____  Date: ____\n\n'+peer.map(x=>'- [ ] '+x).join('\n')+'\n\nStrength: ____\nQuestion: ____\nNext revision: ____\n': '# Three-minute research pitch\n\n'+pitch.map(([time,title,prompt])=>'## '+time+' — '+title+'\n'+prompt+'\nMy notes: ____\n').join('\n');
 function templates(){return shell('Two tools for your next conversation.','Use these with a groupmate or adviser. Download editable Markdown copies; checking a box here is temporary and does not save an assessment.',`<section><h2>Peer-review checklist</h2><p>Read the draft first. Point to a specific passage when giving feedback. Ask the writer to choose their next revision.</p><div class="seminar-checklist">${peer.map(x=>`<label><input type="checkbox">${x}</label>`).join('')}</div><button class="button primary" data-seminar-download="peer">Download peer-review checklist</button></section><section><h2>A three-minute research pitch</h2><dl class="pitch-outline">${pitch.map(([time,title,prompt])=>`<dt>${time} · ${title}</dt><dd>${prompt}</dd>`).join('')}</dl><p>Rehearse aloud and trim to three minutes. One clear question is more useful than a list of technical terms.</p><button class="button primary" data-seminar-download="pitch">Download pitch outline</button></section><p role="status" data-seminar-status></p>`)}
 function checks(){return shell('A quick check before you go further.','Use these prompts to spot a revision worth making. They do not certify that a study is novel, sufficient or approved.',`<section><h2>Is my research gap good enough?</h2><ul><li>Name the uncertainty, not just an unstudied location.</li><li>Show which sources you compared and what they leave unresolved.</li><li>Explain why answering it matters and whether your data can address it.</li><li>Say “in the sources reviewed” until a sufficiently broad search supports more.</li></ul><p><strong>Next move:</strong> Write one sentence linking two sources to one unresolved question.</p></section><section><h2>How many sources do I need?</h2><p>There is no universal number. Follow your department’s requirements while checking coverage: key concepts, relevant methods, foundational work, recent evidence and disagreements. A large reference list cannot replace relevant, critically read sources.</p><p><strong>Next move:</strong> Mark the claim or method decision that still lacks evidence, then search for it.</p><a href="#create/papers">Find paper metadata ↗</a></section><section><h2>Is my title too broad?</h2><ul><li>Can a reader identify the phenomenon or variables and the population/materials?</li><li>Is the setting or scope clear where needed?</li><li>Does the title promise only what your method can establish?</li><li>Can you access the data in the time available?</li></ul><p><strong>Fictional IT revision:</strong> “Technology improves education” → “Offline learning-resource access experiences among selected first-year IT students at one Isabel campus.” This proposes an experience study, not a measured improvement.</p><a href="#create/question">Refine a question and method ↗</a></section><section><h2>Will my work survive clearing the browser?</h2><p>Local work can be removed when site data is cleared or a private session ends. Download a complete workbook backup, keep the file elsewhere, and check it in Backup and recovery. Saving on one device does not sync to another.</p><a href="#backup">Check or restore a backup ↗</a></section>`)}
 function examples(){return shell('Start with a place you recognize.','Fictional starting questions in Isabel and Leyte. These are proposals for discussion, not findings, verified local problems, claims of novelty or evidence that access has been granted.',`<section><h2>Industrial Engineering · Isabel</h2><p>What waiting-time patterns are observed at one campus service desk during selected enrollment hours?</p><p><strong>Evidence:</strong> Permission-based observations, consistent start/end rules, descriptive summaries. Avoid collecting names. Selected periods do not represent all operations.</p></section><section><h2>Information Technology · Leyte</h2><p>How do selected IT students at one Leyte campus describe accessing course materials when connectivity is interrupted?</p><p><strong>Evidence:</strong> Consent-based accounts and a transparent qualitative analysis. Do not infer that an app improves grades from interview preferences.</p></section><section><h2>Education · Isabel</h2><p>How do selected teachers at one Isabel school describe adapting reading activities for learners with varied reading needs?</p><p><strong>Evidence:</strong> Approved recruitment, consent-based interviews and a defensible analysis. Do not collect identifiable learner records without authorization; teacher accounts do not measure an intervention’s effect.</p></section><section><h2>Science · Leyte</h2><p>How does measured pH vary across selected accessible stream sampling points in Leyte during a defined sampling period?</p><p><strong>Evidence:</strong> A justified sampling plan, permissions, safe fieldwork, calibration and recorded conditions. pH alone cannot establish water safety or a pollution source.</p></section><a class="button primary" href="#create/question">Build your own question</a>`)}
 function tools(){return shell('Tools for the work in front of you.','Find sources, build a search, plan a study or prepare for feedback. Your work stays on this device unless you choose to export it.',`${row('#create/papers','Paper finder','Find real Crossref metadata; verify and read the original paper.')}${row('#create/search','Search builder','Group synonyms and build a traceable database search.')}${row('#create/question','Question and method planner','Match a feasible question to evidence and analysis.')}${row('#research','Research projects','Open your source library, Reader, evidence, synthesis and proposal.')}${row('#create/analyze','Explore a dataset','Local descriptive statistics from a bounded CSV.')}${row('#chapters','Chapters 1–4 map','Keep the argument connected across chapters.')}${row('#tools/templates','Peer review and three-minute pitch','Two downloadable templates for useful feedback.')}${row('#tools/checklists','Quick self-checks and FAQs','Gap, source coverage, title scope and backups.')}${row('#examples','Isabel and Leyte examples','IE, IT, Education and Science starting points.')}<details><summary>More research reference guides</summary>${row('#resource/framework','Framework guide','Connect constructs and concepts.')}${row('#resource/matrix','Synthesis matrix guide','Compare evidence across sources.')}</details>`)}
 function resume(){try{const value=localStorage.getItem('rei-last-study-route');if(value&&/^#(?:library\/(?:question|search|read|synthesis|method|claim|ethics|papers|model|study\/[\w-]+)|learn\/[0-5]|lesson\/[0-8](?:\/(?:learn|example|write|check))?|practice\/[\w-]+|workbook|chapters|tools(?:\/(?:templates|checklists))?|examples|create\/(?:question(?:\/question)?|search|papers|analyze)|research(?:\/[\w-]+(?:\/[\w-]+)?)?)$/.test(value))return value;const s=window.REILearningStore?.snapshot();if(s?.resume)return '#lesson/'+s.resume.lesson+'/'+s.resume.step;if(s&&Object.values(s.learningPath?.fields||{}).some(x=>typeof x==='string'&&x.trim()))return '#learn/'+(s.learningPath.last||0);}catch{}return '#learn'}
 const workbookIntro=()=>`<section class="seminar-workbook"><h1>My Workbook</h1><p>Keep your guided writing, notebook and lesson drafts together here.</p><div class="actions"><button class="button primary" data-recovery-export>Download my workbook</button><a href="#backup">Check or restore a backup</a></div><p>Clearing browser data can remove your work. Keep a downloaded copy somewhere safe.</p><p role="status" id="recovery-export-status">Complete JSON backup includes guided writing, notebook, lesson drafts, projects and saved PDFs. Save open forms first.</p><div class="seminar-workbook-links">${row('#guided','Guided writing','Continue the six writing steps; these are not additional lessons.')}${row('#notebook','Notebook','Open your saved ideas and notes.')}${row('#notebook/draft','Detailed lesson drafts','Open earlier saved writing without moving or replacing it.')}${row('#research','Research projects','Continue your evidence and proposal.')} </div><h2>Your guided workbook</h2></section>`;
 function ethicsWithDepth(){let view=ethics();const D=window.REILessonDepth;if(D){view=view.replace('<section><h2>Check your decision',D.concept('ethics')+D.worked('ethics')+'<section><h2>Check your decision');view=view.replace('<section><h2>Now do this',D.application('ethics')+'<section><h2>Now do this');}return view;}
 function render(parts){const p=parts[0];return p==='recap'?recap():p==='chapters'?chapters():p==='examples'?examples():p==='library'?ethicsWithDepth():parts[1]==='templates'?templates():parts[1]==='checklists'?checks():tools()}
 document.addEventListener('change',e=>{if(e.target.name==='ethics-check')document.querySelector('[data-ethics-feedback]').textContent=e.target.value==='revise'?'Yes. Preserve the meaning, use your own structure and cite the source; mark any exact wording as a quotation with a locator.':'A citation credits the source but does not mark copied wording. Rewrite independently or quote with a locator.'});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-seminar-download]');if(!b)return;const id=b.dataset.seminarDownload;if(!['peer','pitch'].includes(id))return;const url=URL.createObjectURL(new Blob([templateText(id)],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='rei-'+id+'-template.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);document.querySelector('[data-seminar-status]').textContent='Download requested. Check that your browser kept the file.'});
 const flow=[
  {id:'question',title:'Find a question worth asking.',short:'Question',lesson:'#library/question',tool:'#create/question/question',toolLabel:'Shape your question',write:'#learn/1',idea:sessions[1][1],example:sessions[1][2],action:sessions[1][3],purpose:'Leave with a focused question and a reason to investigate it.'},
  {id:'search',title:'Follow the evidence.',short:'Search',lesson:'#library/search',tool:'#create/search',toolLabel:'Build your search',write:'#learn/2',idea:sessions[2][1],example:sessions[2][2],action:sessions[2][3],purpose:'Keep a search you can repeat, with sources you can trace.'},
  {id:'read',title:'Look closer before you believe.',short:'Read',lesson:'#library/read',tool:'#create/papers',toolLabel:'Find a paper to read',write:'#learn/2',idea:'Separate what the source reports from what you infer. Record the question, method, result and boundary.',example:'A Leyte-campus volunteer survey can describe its respondents; it cannot speak for every student in the province.',action:'Save one finding, its exact source location and an important limitation.',purpose:'Leave with one accurate, source-linked evidence note.'},
  {id:'synthesis',title:'Find the thread between studies.',short:'Connect',lesson:'#library/synthesis',tool:'#research',toolLabel:'Compare evidence in a project',write:'#learn/3',idea:sessions[3][1],example:sessions[3][2],action:sessions[3][3],purpose:'Explain a pattern, a difference and a bounded uncertainty.'},
  {id:'method',title:'Give your question a workable plan.',short:'Plan',lesson:'#library/method',tool:'#create/question',toolLabel:'Check the question–method fit',write:'#learn/4',idea:sessions[4][1],example:sessions[4][2],action:sessions[4][3],purpose:'Align the objective, data, analysis and practical safeguards.'},
  {id:'claim',title:'Write only what the evidence can carry.',short:'Write',lesson:'#library/claim',tool:'#chapters',toolLabel:'Connect Chapters 1–4',write:'#learn/5',idea:sessions[5][1],example:sessions[5][2],action:sessions[5][3],purpose:'Leave with a clear, bounded argument and one useful revision.'},
  {id:'ethics',title:'Stand behind the work.',short:'Review',lesson:'#library/ethics',tool:'#tools/templates',toolLabel:'Prepare peer feedback or a pitch',write:'#learn/5',idea:'Credit ideas and exact words, protect participants and disclose permitted AI use.',example:'Before interviewing Isabel students, obtain the required review and voluntary consent. An adviser’s permission does not replace consent.',action:'Audit a paragraph, check consent/privacy plans and name one question for your adviser.',purpose:'Review citation, consent and authorship before sharing.'}
 ];
 function journey(){return '<div class="flow-journey compact-journey" id="flow-journey"><header><h2>Choose your next lesson.</h2><p>Read the explanation, follow the reasoning, test a decision and apply it to your own study. Keep your writing in <a href="#workbook">My work</a>.</p></header><ol class="compact-lessons">'+flow.map((s,i)=>'<li id="flow-'+s.id+'" data-flow-stage="'+s.id+'"><a href="'+s.lesson+'"><span>'+String(i+1).padStart(2,'0')+'</span><strong>'+esc(s.short)+'</strong><span aria-hidden="true">↗</span></a></li>').join('')+'</ol></div>'}
 function resources(){return '<details class="home-reference-summary" id="flow-resources"><summary>References and tools for your study</summary><div class="compact-reference-links">'+row('#chapters','Chapters 1–4','Keep your problem, objectives and methods aligned.')+row('#tools/templates','Peer review and pitch','Prepare useful feedback and a three-minute explanation.')+row('#tools/checklists','Quick self-checks','Gap, source coverage and title scope.')+row('#library/papers','Read real papers','Inspect original evidence with source-linked practice.')+row('#library/model','A worked proposal','See a complete illustrative project.')+row('#research','Research projects','Sources, PDFs, evidence and proposal writing.')+'</div></details>'}
 function stageFor(hash){const parts=hash.replace(/^#/,'').split('/');if(parts[0]==='library')return flow.find(s=>s.id===parts[1])||flow[2];if(parts[0]==='learn'&&parts[1]!==undefined)return [flow[0],flow[0],flow[1],flow[3],flow[4],flow[5]][+parts[1]];if(parts[0]==='lesson')return [flow[0],flow[0],flow[1],flow[3],flow[3],flow[0],flow[4],flow[4],flow[5]][+parts[1]];if(parts[0]==='create')return parts[1]==='question'?(parts[2]==='question'?flow[0]:flow[4]):parts[1]==='analyze'?flow[4]:parts[1]==='papers'?flow[2]:flow[1];if(parts[0]==='practice')return ({recall:flow[0],question:flow[0],verify:flow[1],gap:flow[3],claim:flow[5],alignment:flow[4],review:flow[6],revisit:flow[6]})[parts[1]]||null;if(parts[0]==='resource')return parts[1]==='matrix'?flow[3]:flow[4];if(parts[0]==='workshop')return [flow[0],flow[3],flow[4]][+parts[1]]||null;if(parts[0]==='research')return ['claims','proposal'].includes(parts[2])?flow[5]:parts[2]==='design'?flow[4]:['library','reader'].includes(parts[2])?flow[2]:flow[3];if(parts[0]==='chapters')return flow[5];if(parts[0]==='tools')return parts[1]==='templates'?flow[6]:flow[0];return null}
 function bridge(stage){const i=flow.indexOf(stage),next=flow[i+1];return `<section class="flow-bridge" aria-label="Continue your research"><h2>Carry this into your study.</h2><p>${stage.action}</p><div class="flow-actions"><a class="button primary" href="${stage.tool}">${stage.toolLabel}</a><a href="${stage.write}">Write it into my study ↗</a></div><p>${next?`Then continue to <a href="${next.lesson}">${next.short.toLowerCase()}: ${next.title}</a>`:'Ready for feedback? <a href="#workbook">Review and download your work</a>.'}</p><a href="#home/${stage.id}">Return to this place in the journey</a></section>`}
 window.REISeminar={render,nav,resume,workbookIntro,sections,templateText,flow,journey,resources,stageFor,bridge};
})();
